  const k=Math.max(W/BG_IMG.width,H/BG_IMG.height),iw=BG_IMG.width*k,ih=BG_IMG.height*k;
  x.drawImage(BG_IMG,(W-iw)/2,(H-ih)*SKIES[skyName].y,iw,ih);   // balance sky and grass in the crop
