    x.globalCompositeOperation='multiply';const n=x.createLinearGradient(0,0,0,H);n.addColorStop(0,'#2e2250');n.addColorStop(.6,'#553a68');n.addColorStop(1,'#3a3a4a');x.fillStyle=n;x.fillRect(0,0,W,H);
