  const W=1024,H=512,cv=document.createElement('canvas');cv.width=W;cv.height=H;const x=cv.getContext('2d');
  const g=x.createLinearGradient(0,0,0,H);g.addColorStop(0,'#FFE9F1');g.addColorStop(.5,'#FBCFE0');g.addColorStop(1,'#EFA9C4');x.fillStyle=g;x.fillRect(0,0,W,H);
