const panel=document.getElementById('panel');document.getElementById('back').onclick=()=>{location.hash='';};
function route(){const h=location.hash.slice(1);
  if(h==='about'||h==='faq'){const A=h==='about';document.getElementById('ptitle').textContent=A?'About':'FAQ';document.getElementById('psub').textContent=A?'The story behind Pink Plume':'Questions, answered';
    document.getElementById('pgrid').innerHTML=`<div class="card" style="grid-column:1/-1;padding:24px"><div class="t">${A?'About page placeholder — your story, your process and the hands behind each piece go here.':'FAQ placeholder — shipping, sizing, care and custom orders go here.'}</div></div>`;panel.classList.add('on');panel.scrollTop=0;return;}
  if(h==='shop'||cats.some(c=>c.id===h)){panel.classList.remove('on');enterRoom();return;}
  exitRoom();
  if(h==='shop'){document.getElementById('ptitle').textContent='Shop all';document.getElementById('psub').textContent='Everything in the cloud';
    document.getElementById('pgrid').innerHTML=cats.map(c=>`<a class="card" href="#${c.id}" style="text-decoration:none;color:inherit"><div class="img"></div><div class="t">${c.name}<span>Browse →</span></div></a>`).join('');panel.classList.add('on');panel.scrollTop=0;return;}
  const c=cats.find(c=>c.id===h);if(!c){panel.classList.remove('on');return;}
  document.getElementById('ptitle').textContent=c.name;document.getElementById('psub').textContent='Shop page placeholder';
  document.getElementById('pgrid').innerHTML=Array.from({length:6},(_,i)=>`<div class="card"><div class="img"></div><div class="t">${c.name.replace(/s$/,'')} piece ${i+1}<span>$—</span></div></div>`).join('');
  panel.classList.add('on');panel.scrollTop=0;}
